1	/**
2	 * The human-intervention counter: a harness *outside* the command it scores.
3	 *
4	 * The zero-manual-steps gate is the half of the oracle that inflates quietly,
5	 * and the way it inflates is by being scored by the thing under test. A run
6	 * that reports its own intervention count reports the number a bad stage would
7	 * report. So this module never runs a stage: it snapshots the disk, spawns
8	 * `versionless run` exactly once as a child process, re-snapshots, diffs, and
9	 * writes the record. `run` is not asked what it did; it is observed.
10	 *
11	 * Four counters, and the gate passes only when all four are zero. A zero here
12	 * is asserted rather than assumed — each counter names what it looked at, so
13	 * "no evidence of hand-help" and "evidence of no hand-help" stay different
14	 * statements.
15	 *
16	 * **C1 — worktree mutation outside the declared write set.** Every tracked path
17	 * in the checkout, plus the application root and the lane parent, hashed before
18	 * and after. The command declares its write set (`--out`, `--record`, and the
19	 * `evidence/**` paths it names); a changed or created path outside that set is
20	 * one intervention, named.
21	 *
22	 * **C2 — prompt / stdin reads.** The child is spawned with stdin `ignore` and
23	 * `CI=1`, so a read of stdin cannot be answered by construction. A child that
24	 * emits no stdout for longer than the stage budget is a **hang**, which the
25	 * charter classifies as a defect — scored `defect:hang`, never as an
26	 * intervention and never as a refusal.
27	 *
28	 * **C3 — invocations.** One spawn is permitted. A second command — a retry with
29	 * different flags included — is one intervention per retry, because choosing
30	 * the flags for the retry is exactly the operator decision this gate counts.
31	 *
32	 * **C4 — authoring-home writes.** The eight authoring homes, hashed before and
33	 * after. A create or a modify in any of them is one intervention per file,
34	 * named. This is the counter aimed at silent manual residue: an application
35	 * that "ran unattended" while a fixture was quietly authored beside it.
36	 *
37	 * Nothing here throws. A harness that raises where it is supposed to observe
38	 * loses the record, and the record is the whole point; every failure this can
39	 * meet is a classification instead (`defect:no-run-record`,
40	 * `defect:spawn-failed`).
41	 */
42	
43	import { spawn } from 'node:child_process';
44	import { execFile } from 'node:child_process';
45	import { readFile, readdir, stat } from 'node:fs/promises';
46	import { promisify } from 'node:util';
47	import * as path from 'pathe';
48	import { sha256 } from '../../../core/src/receipts/canonicalize.ts';
49	import { displayPath, writeRecord } from './record.ts';
50	
51	const execute = promisify(execFile);
52	
53	export const INTERVENTION_COUNT_SCHEMA = 'versionless.intervention-count.v1';
54	
55	/** Where the harness record is filed beside a run record at `<file>`. */
56	export function interventionRecordPathFor(runRecord: string): string {
57		return `${runRecord}.interventions.json`;
58	}
59	
60	/** The default stage budget: the longest a stage may be silent before it hangs. */
61	export const DEFAULT_STAGE_BUDGET_MS = 900_000;
62	
63	/**
64	 * The eight authoring homes, as the plan validation names them.
65	 *
66	 * A `prefix` matches everything below a directory; a `file` is exact; a
67	 * `suffix` pair matches a file below a prefix whose name ends the given way.
68	 * They are matched against checkout-relative POSIX paths.
69	 */
70	export type AuthoringHome = Readonly<{
71		home: string;
72		kind: 'prefix' | 'file' | 'prefix-suffix';
73		prefix?: string;
74		suffixes?: readonly string[];
75	}>;
76	
77	export const AUTHORING_HOMES: readonly AuthoringHome[] = Object.freeze([
78		Object.freeze({ home: 'fixtures/**', kind: 'prefix' as const, prefix: 'fixtures/' }),
79		Object.freeze({
80			home: 'packages/cli/src/fixture/**',
81			kind: 'prefix' as const,
82			prefix: 'packages/cli/src/fixture/',
83		}),
84		Object.freeze({
85			home: 'packages/cli/src/witness/**',
86			kind: 'prefix' as const,
87			prefix: 'packages/cli/src/witness/',
88		}),
89		Object.freeze({
90			home: 'packages/core/src/receipts/witness-*.ts',
91			kind: 'prefix-suffix' as const,
92			prefix: 'packages/core/src/receipts/witness-',
93			suffixes: Object.freeze(['.ts']),
94		}),
95		Object.freeze({
96			home: 'packages/core/src/receipts/capability-coverage.ts',
97			kind: 'file' as const,
98			prefix: 'packages/core/src/receipts/capability-coverage.ts',
99		}),
100		Object.freeze({
101			home: 'packages/core/src/corpus/conformance.ts',
102			kind: 'file' as const,
103			prefix: 'packages/core/src/corpus/conformance.ts',
104		}),
105		Object.freeze({
106			home: 'packages/trust/src/generate.ts',
107			kind: 'file' as const,
108			prefix: 'packages/trust/src/generate.ts',
109		}),
110		Object.freeze({
111			home: 'packages/cli/src/fixture/legacy-candidate-ingest.ts',
112			kind: 'file' as const,
113			prefix: 'packages/cli/src/fixture/legacy-candidate-ingest.ts',
114		}),
115		Object.freeze({
116			home: '.versionless/work/**/*.{mjs,sh}',
117			kind: 'prefix-suffix' as const,
118			prefix: '.versionless/work/',
119			suffixes: Object.freeze(['.mjs', '.sh']),
120		}),
121	]);
122	
123	/** The authoring home a checkout-relative path sits in, or `null`. */
124	export function authoringHomeOf(relative: string): string | null {
125		for (const home of AUTHORING_HOMES) {
126			const prefix = home.prefix ?? '';
127			if (home.kind === 'file') {
128				if (relative === prefix) return home.home;
129				continue;
130			}
131			if (!relative.startsWith(prefix)) continue;
132			if (home.kind === 'prefix') return home.home;
133			if ((home.suffixes ?? []).some((suffix) => relative.endsWith(suffix))) return home.home;
134		}
135		return null;
136	}
137	
138	export type SpawnAttempt = Readonly<{
139		/** The arguments handed to this runtime, as the harness spawned them. */
140		argv: readonly string[];
141		exitCode: number | null;
142		signal: string | null;
143		/** A child killed for emitting no stdout inside the stage budget. */
144		hang: boolean;
145		stdoutBytes: number;
146		stderrBytes: number;
147		startedAt: string;
148		endedAt: string;
149		/** Set when the child could not be spawned at all. */
150		spawnError?: string;
151	}>;
152	
153	export type InterventionCountRecord = Readonly<{
154		schemaVersion: typeof INTERVENTION_COUNT_SCHEMA;
155		flow: 'intervention-count';
156		application: string;
157		lane: string;
158		runRecord: string;
159		/** The paths the command declared it writes. Everything else is counted. */
160		writeSet: readonly string[];
161		invocations: number;
162		stdinReads: number;
163		mutatedPathsOutsideWriteSet: readonly string[];
164		authoringPathsTouched: readonly string[];
165		interventionCount: number;
166		exitCode: number;
167		terminalClassification: string;
168		attempts: readonly SpawnAttempt[];
169		observation: Readonly<{
170			stdio: string;
171			environment: Readonly<Record<string, string>>;
172			stageBudgetMs: number;
173			trackedPathsSource: 'git' | 'directory-walk';
174			pathsObservedBefore: number;
175			pathsObservedAfter: number;
176			authoringHomes: readonly string[];
177		}>;
178		notEstablished: readonly string[];
179	}>;
180	
181	export type InterventionCountDeclarations = Readonly<{
182		appRoot: string;
183		/** The lane `run` was told to write, which is the first declared write path. */
184		out: string;
185		/** Where `run` was told to file its own record; the second declared write path. */
186		runRecord: string;
187		/** The checkout whose tracked paths are hashed. Defaults to the working directory. */
188		root: string;
189		/** The `evidence/**` paths the command names, if any. */
190		evidencePaths: readonly string[];
191		/**
192		 * The command lines spawned, in order. One is the permitted case; a second
193		 * entry is a retry, and a retry is an operator decision this gate counts.
194		 */
195		attempts: readonly (readonly string[])[];
196		stageBudgetMs: number;
197	}>;
198	
199	const NOT_ESTABLISHED: readonly string[] = Object.freeze([
200		'This is a count of interventions this harness could observe from outside the command: bytes on disk that changed, how many times a process was spawned, and whether stdin could have been read. It is not a statement that the run produced a working application.',
201		'`node_modules` and `.git` are not walked below the application root or the lane parent. A change inside an installed dependency tree is not observed here, and the counters do not establish that none happened.',
202		'A directory walk observes files. A permission change, a symlink retarget, or a file whose bytes were rewritten identically is not a change this harness counts.',
203		'`stdinReads: 0` is a construction, not a measurement of the child’s syscalls: the child was spawned with stdin `ignore` and `CI=1`, so a prompt had nothing to read and no answer could have been supplied.',
204		'A hang is a defect, not a refusal and not an intervention. It says the child emitted no stdout inside the stage budget; it does not establish what the child would have done given longer.',
205		'A refusal exit is a terminal outcome, not an intervention. Nothing here establishes what the run would have reached had the refusal not fired.',
206	]);
207	
208	type Snapshot = ReadonlyMap<string, string>;
209	
210	const SKIPPED_DIRECTORIES: readonly string[] = Object.freeze(['node_modules', '.git']);
211	
212	async function hashFile(file: string): Promise<string | null> {
213		try {
214			return sha256(await readFile(file));
215		} catch {
216			return null;
217		}
218	}
219	
220	async function walkFiles(directory: string, into: string[]): Promise<void> {
221		let entries;
222		try {
223			entries = await readdir(directory, { withFileTypes: true });
224		} catch {
225			return;
226		}
227		for (const entry of entries) {
228			if (SKIPPED_DIRECTORIES.includes(entry.name)) continue;
229			const full = path.join(directory, entry.name);
230			if (entry.isDirectory()) {
231				await walkFiles(full, into);
232				continue;
233			}
234			if (entry.isFile()) into.push(full);
235		}
236	}
237	
238	/** Every tracked path in the checkout, or `null` when Git cannot answer. */
239	async function trackedPaths(root: string): Promise<readonly string[] | null> {
240		try {
241			const { stdout } = await execute('git', ['ls-files', '-z'], {
242				cwd: root,
243				maxBuffer: 256 * 1024 * 1024,
244			});
245			const files = stdout.split('\0').filter((entry) => entry !== '');
246			return files.length === 0 ? null : files.map((file) => path.join(root, file));
247		} catch {
248			return null;
249		}
250	}
251	
252	/**
253	 * Hash every path this harness watches, once.
254	 *
255	 * The set is the same before and after by construction — it is recomputed both
256	 * times, so a file created by the child is present in the second reading and
257	 * absent from the first, which is how a creation is observed rather than
258	 * inferred.
259	 */
260	export async function snapshotWatchedPaths(
261		declarations: Pick<InterventionCountDeclarations, 'root' | 'appRoot' | 'out'>,
262	): Promise<{ snapshot: Snapshot; source: 'git' | 'directory-walk' }> {
263		const root = path.resolve(declarations.root);
264		const tracked = await trackedPaths(root);
265		const files: string[] = tracked === null ? [] : [...tracked];
266		if (tracked === null) await walkFiles(root, files);
267		await walkFiles(path.resolve(declarations.appRoot), files);
268		await walkFiles(path.dirname(path.resolve(declarations.out)), files);
269		const snapshot = new Map<string, string>();
270		for (const file of new Set(files.map((file) => path.resolve(file)))) {
271			const digest = await hashFile(file);
272			if (digest !== null) snapshot.set(file, digest);
273		}
274		return { snapshot, source: tracked === null ? 'directory-walk' : 'git' };
275	}
276	
277	/** Whether a path is one the command declared it writes. */
278	function insideWriteSet(file: string, writeSet: readonly string[]): boolean {
279		return writeSet.some(
280			(declared) => file === declared || file.startsWith(`${declared}${path.sep}`),
281		);
282	}
283	
284	function changedPaths(before: Snapshot, after: Snapshot): readonly string[] {
285		const changed: string[] = [];
286		for (const [file, digest] of after) if (before.get(file) !== digest) changed.push(file);
287		for (const file of before.keys()) if (!after.has(file)) changed.push(file);
288		return changed.sort();
289	}
290	
291	type RunReading = Readonly<{ outcome?: unknown; refusal?: unknown; stages?: unknown }>;
292	
293	/**
294	 * The terminal classification, read from the run's own record.
295	 *
296	 * The record is read rather than trusted for the count: what a run may state
297	 * about itself is what it refused with and which stages it reached, and those
298	 * are the facts this classification needs. The count is never taken from it.
299	 */
300	export function classifyTerminal(
301		reading: RunReading | null,
302		exitCode: number,
303		hang: boolean,
304	): string {
305		if (hang) return 'defect:hang';
306		if (reading === null) return 'defect:no-run-record';
307		const outcome = typeof reading.outcome === 'string' ? reading.outcome : 'not-recorded';
308		if (outcome === 'refused') {
309			const refusal = reading.refusal;
310			const code =
311				typeof refusal === 'object' && refusal !== null && 'code' in refusal
312					? String((refusal as { code: unknown }).code)
313					: 'unnamed';
314			return `refused:${code}`;
315		}
316		if (outcome === 'defect') {
317			const defect = (reading as { defect?: unknown }).defect;
318			const stage =
319				typeof defect === 'object' && defect !== null && 'stage' in defect
320					? String((defect as { stage: unknown }).stage)
321					: 'unnamed';
322			return `defect:${stage}`;
323		}
324		if (outcome === 'proceeded') {
325			const stages = Array.isArray(reading.stages) ? reading.stages : [];
326			const everyStageRan =
327				stages.length > 0 &&
328				stages.every(
329					(stage) =>
330						typeof stage === 'object' &&
331						stage !== null &&
332						(stage as { status?: unknown }).status === 'ran',
333				);
334			if (exitCode === 0 && everyStageRan) return 'proven';
335			return 'defect:stages-not-all-run';
336		}
337		if (outcome === 'not-run') return 'defect:no-stage-ran';
338		return 'defect:outcome-not-classified';
339	}
340	
341	async function readRunReading(file: string): Promise<RunReading | null> {
342		try {
343			const parsed: unknown = JSON.parse(await readFile(file, 'utf8'));
344			return typeof parsed === 'object' && parsed !== null ? (parsed as RunReading) : null;
345		} catch {
346			return null;
347		}
348	}
349	
350	/**
351	 * Spawn one child and watch it: stdin closed, `CI=1`, stdout the only heartbeat.
352	 *
353	 * The budget re-arms on every stdout chunk rather than bounding the whole run,
354	 * because machine time is explicitly not an intervention — a stage that takes
355	 * twenty minutes and says so is not the thing being counted. A child that says
356	 * nothing for the whole budget is.
357	 */
358	export async function spawnWatched(
359		argv: readonly string[],
360		options: Readonly<{ cwd: string; stageBudgetMs: number }>,
361	): Promise<SpawnAttempt> {
362		const startedAt = new Date().toISOString();
363		return await new Promise<SpawnAttempt>((resolve) => {
364			let stdoutBytes = 0;
365			let stderrBytes = 0;
366			let hang = false;
367			let settled = false;
368			const child = spawn(process.execPath, [...argv], {
369				cwd: options.cwd,
370				stdio: ['ignore', 'pipe', 'pipe'],
371				env: { ...process.env, CI: '1' },
372			});
373			let timer: NodeJS.Timeout | null = null;
374			const finish = (attempt: SpawnAttempt): void => {
375				if (settled) return;
376				settled = true;
377				if (timer !== null) clearTimeout(timer);
378				resolve(attempt);
379			};
380			const arm = (): void => {
381				if (timer !== null) clearTimeout(timer);
382				timer = setTimeout(() => {
383					hang = true;
384					child.kill('SIGKILL');
385				}, options.stageBudgetMs);
386				timer.unref();
387			};
388			child.stdout?.on('data', (chunk: Buffer) => {
389				stdoutBytes += chunk.length;
390				arm();
391			});
392			child.stderr?.on('data', (chunk: Buffer) => {
393				stderrBytes += chunk.length;
394			});
395			child.on('error', (error: Error) => {
396				finish(
397					Object.freeze({
398						argv: Object.freeze([...argv]),
399						exitCode: null,
400						signal: null,
401						hang: false,
402						stdoutBytes,
403						stderrBytes,
404						startedAt,
405						endedAt: new Date().toISOString(),
406						spawnError: error.message,
407					}),
408				);
409			});
410			child.on('close', (code: number | null, signal: string | null) => {
411				finish(
412					Object.freeze({
413						argv: Object.freeze([...argv]),
414						exitCode: code,
415						signal,
416						hang,
417						stdoutBytes,
418						stderrBytes,
419						startedAt,
420						endedAt: new Date().toISOString(),
421					}),
422				);
423			});
424			arm();
425		});
426	}
427	
428	/** The argv this harness spawns `run` with, from the declarations it was given. */
429	export function runArgvFor(
430		cliEntry: string,
431		declarations: Pick<InterventionCountDeclarations, 'appRoot' | 'out' | 'runRecord'>,
432		forwarded: readonly string[],
433	): readonly string[] {
434		return Object.freeze([
435			'--experimental-strip-types',
436			cliEntry,
437			'run',
438			declarations.appRoot,
439			'--out',
440			declarations.out,
441			'--record',
442			declarations.runRecord,
443			...forwarded,
444		]);
445	}
446	
447	/** The CLI entry this harness spawns, resolved from this module rather than cwd. */
448	export function cliEntryPath(): string {
449		return path.resolve(path.dirname(new URL(import.meta.url).pathname), '../cli.ts');
450	}
451	
452	/**
453	 * Snapshot, spawn, re-snapshot, count.
454	 *
455	 * The order matters and is the whole method: nothing is read from the command
456	 * about itself except which refusal it named, and every counter is a difference
457	 * between two readings this harness took.
458	 */
459	export async function countInterventions(
460		declarations: InterventionCountDeclarations,
461	): Promise<InterventionCountRecord> {
462		const root = path.resolve(declarations.root);
463		const laneAbsolute = path.resolve(declarations.out);
464		const runRecordAbsolute = path.resolve(declarations.runRecord);
465		const harnessRecordAbsolute = path.resolve(interventionRecordPathFor(declarations.runRecord));
466		const writeSet = [
467			laneAbsolute,
468			runRecordAbsolute,
469			harnessRecordAbsolute,
470			...declarations.evidencePaths.map((entry) => path.resolve(root, entry)),
471		];
472		const before = await snapshotWatchedPaths(declarations);
473		const attempts: SpawnAttempt[] = [];
474		for (const argv of declarations.attempts)
475			attempts.push(
476				await spawnWatched(argv, { cwd: root, stageBudgetMs: declarations.stageBudgetMs }),
477			);
478		const after = await snapshotWatchedPaths(declarations);
479		const last = attempts.at(-1);
480		const mutated: string[] = [];
481		const authoring: string[] = [];
482		for (const file of changedPaths(before.snapshot, after.snapshot)) {
483			const relative = path.relative(root, file).split(path.sep).join('/');
484			const home = authoringHomeOf(relative);
485			if (home !== null) {
486				authoring.push(displayPath(file));
487				continue;
488			}
489			if (insideWriteSet(file, writeSet)) continue;
490			mutated.push(displayPath(file));
491		}
492		const hang = last?.hang === true;
493		const exitCode = last === undefined ? 1 : (last.exitCode ?? 1);
494		const reading = hang ? null : await readRunReading(runRecordAbsolute);
495		const invocations = attempts.length;
496		const stdinReads = 0;
497		const interventionCount =
498			Math.max(invocations - 1, 0) + stdinReads + mutated.length + authoring.length;
499		const classification =
500			last?.spawnError === undefined
501				? classifyTerminal(reading, exitCode, hang)
502				: 'defect:spawn-failed';
503		return Object.freeze({
504			schemaVersion: INTERVENTION_COUNT_SCHEMA,
505			flow: 'intervention-count' as const,
506			application: displayPath(declarations.appRoot),
507			lane: displayPath(declarations.out),
508			runRecord: displayPath(declarations.runRecord),
509			writeSet: Object.freeze(writeSet.map((entry) => displayPath(entry))),
510			invocations,
511			stdinReads,
512			mutatedPathsOutsideWriteSet: Object.freeze(mutated),
513			authoringPathsTouched: Object.freeze(authoring),
514			interventionCount,
515			exitCode,
516			terminalClassification: classification,
517			attempts: Object.freeze(attempts),
518			observation: Object.freeze({
519				stdio: "['ignore', 'pipe', 'pipe']",
520				environment: Object.freeze({ CI: '1' }),
521				stageBudgetMs: declarations.stageBudgetMs,
522				trackedPathsSource: before.source,
523				pathsObservedBefore: before.snapshot.size,
524				pathsObservedAfter: after.snapshot.size,
525				authoringHomes: Object.freeze(AUTHORING_HOMES.map((home) => home.home)),
526			}),
527			notEstablished: NOT_ESTABLISHED,
528		});
529	}
530	
531	/** File the harness record beside the run record it scored. */
532	export async function writeInterventionRecord(
533		runRecord: string,
534		record: InterventionCountRecord,
535	): Promise<string> {
536		const target = interventionRecordPathFor(runRecord);
537		await writeRecord(target, record);
538		return target;
539	}
540	
541	/** Whether the lane parent exists, so a reader knows the walk had something to read. */
542	export async function directoryExists(directory: string): Promise<boolean> {
543		try {
544			return (await stat(directory)).isDirectory();
545		} catch {
546			return false;
547		}
548	}
549	
550	/** The count as an operator reads it: the four counters, then what they name. */
551	export function renderInterventionCount(record: InterventionCountRecord): string {
552		const lines = [
553			`application: ${record.application}`,
554			`lane: ${record.lane}`,
555			`run record: ${record.runRecord}`,
556			'',
557			`invocations                       ${String(record.invocations)}`,
558			`stdin reads                       ${String(record.stdinReads)}`,
559			`mutated outside the write set     ${String(record.mutatedPathsOutsideWriteSet.length)}`,
560			`authoring-home paths touched      ${String(record.authoringPathsTouched.length)}`,
561			'',
562			`intervention count: ${String(record.interventionCount)}`,
563			`terminal classification: ${record.terminalClassification}`,
564			`exit code: ${String(record.exitCode)}`,
565			'',
566		];
567		for (const file of record.mutatedPathsOutsideWriteSet) lines.push(`mutated: ${file}`);
568		for (const file of record.authoringPathsTouched) lines.push(`authoring home: ${file}`);
569		if (
570			record.mutatedPathsOutsideWriteSet.length === 0 &&
571			record.authoringPathsTouched.length === 0
572		)
573			lines.push(
574				`no path outside the declared write set changed, across ${String(record.observation.pathsObservedAfter)} observed path(s).`,
575			);
576		lines.push('');
577		for (const line of record.notEstablished) lines.push(`not established: ${line}`);
578		return `${lines.join('\n')}\n`;
579	}
