45	import { main as runAngularFuxaStandaloneCohort } from './fixture/angular-fuxa-standalone-cohort-run.ts';
46	import { main as runAngularFuxaTemplateCompiler } from './fixture/angular-fuxa-template-compiler-run.ts';
47	import { main as runVite8SharedAdapterCohort } from './fixture/vite8-shared-adapter-cohort-run.ts';
48	import { runDirectDomInventory } from './analysis/direct-dom-inventory.ts';
49	import {
50		runSynthesizedWitnessRealApp,
51		runWitnessRealApps,
52		synthesizedWitnessOutputDir,
53		verifyWitnessRealApps,
54	} from './witness/real-app-run.ts';
55	import { readJourneyDeclaration } from './witness/journey-synthesis/driver.ts';
56	import type { WitnessRealAppRun } from '../../core/src/index.ts';
57	import {
58		runWitnessAngularRealworld,
59		verifyWitnessAngularRealworld,
60	} from './witness/angular-realworld-run.ts';
61	import { verifyLinkedWitnessProvenance } from './witness/provenance.ts';
62	import { isOperatorCommand, runOperatorCommand } from './operator/flows.ts';
63	
64	const [command, ...rawArgs] = process.argv.slice(2);
65	const args = rawArgs.filter((arg) => arg !== '--');
66	const valueAfter = (flag: string): string | undefined => {
67		const index = args.indexOf(flag);
68		return index >= 0 ? args[index + 1] : undefined;
69	};
70	try {
71		if (isOperatorCommand(command)) {
72			// The framework-neutral operator surface. These flows compose the same
73			// frozen public APIs the fixture drivers compose; they add argument
74			// validation, a JSON mode and refusals, and no migration decision.
75			const outcome = await runOperatorCommand(command, rawArgs);
76			process.stdout.write(outcome.text);
77			if (outcome.exitCode !== 0) process.exitCode = outcome.exitCode;
78		} else if (command === 'fixture:ingest') {
79			// The network acquisition path for the fixtures this repository already
80			// published evidence for. The allowlist below is not an admission gate:
81			// admitting an application the pipeline has never seen is `versionless
82			// ingest <source-root>`, routed above by isOperatorCommand, which reads a
83			// source already on disk and consults no list. What this list still gates
84			// is which remote repositories this command may reach over the network,
85			// under the exact purpose-bound consent each fixture's ingest module
86			// carries — a record of consent given, not a permission to migrate. It is
87			// read here and by `fixture:verify` below, and nowhere else.
88			const fixture = valueAfter('--fixture');
89			const ingest = isLegacyCandidateId(fixture)
90				? (options: { allowNetwork: boolean; consentId?: string }) =>
91						ingestLegacyCandidate({ ...options, fixture })
92				: fixture === 'angular-phonecat'
93					? ingestAngularPhonecat
94					: fixture === 'react-realworld-cra1-vite8'
95						? ingestReactRealworld
96						: fixture === 'react-boilerplate-v4-node24'
97							? ingestReactBoilerplateNode24
98							: ingestFixture;
99			if (
100				![
101					'react-boilerplate-v4',
102					'react-boilerplate-v4-node24',
103					'react-realworld-cra1-vite8',
104					'angular-phonecat',
105					'react-papercups-v1-0-0',
106				].includes(fixture ?? '')
107			)
108				throw new Error('Unsupported fixture');
109			const result = await ingest({
110				allowNetwork: args.includes('--allow-network'),
111				consentId: valueAfter('--consent-id'),
112			});
113			console.log(
114				JSON.stringify({
115					result: 'ingested',
116					fixture: result.manifest.id,
117					consentId: result.consent.consentId,
118				}),
119			);
120		} else if (command === 'fixture:verify' && isLegacyCandidateId(valueAfter('--fixture'))) {
121			if (!args.includes('--offline'))
122				throw new Error('Legacy corpus evidence verification requires --offline');
123			const verification = await verifyLegacyCandidateEvidence(
124				legacyCandidateConfig(valueAfter('--fixture')),
125			);
126			console.log(
127				JSON.stringify({
128					result: 'pass',
129					fixture: verification.fixture,
130					checks: verification.checks.length,
131					digest: verification.digest,
132				}),
133			);
134		} else if (command === 'fixture:verify') {
135			const fixture = valueAfter('--fixture');
136			if (
137				![
138					'react-boilerplate-v4',
139					'react-boilerplate-v4-node24',
140					'react-boilerplate-v4-vite8',
141					'react-boilerplate-v4-data-flow',
142					'react-boilerplate-v4-composed',
143					'angular-phonecat',
144					'angular-phonecat-composed',
145					'angular-phonecat-vite8',
146					'angular-phonecat-route-resolve',
147				].includes(fixture ?? '') ||
148				!args.includes('--offline')
149			)
150				throw new Error('Fixture verification requires a supported fixture and --offline');
151			const receiptPath = valueAfter('--receipt');
152			if (!receiptPath) throw new Error('--receipt is required');
153			const receipt =
154				fixture === 'angular-phonecat'
155					? await verifyAngularPhonecat({ receiptPath })
156					: fixture === 'angular-phonecat-composed'
157						? await verifyAngularPhonecatComposed({ receiptPath })
158						: fixture === 'angular-phonecat-vite8'
159							? await verifyAngularPhonecatVite8({ receiptPath })
160							: fixture === 'angular-phonecat-route-resolve'
161								? await verifyAngularPhonecatRouteResolve({ receiptPath })
162								: fixture === 'react-boilerplate-v4-node24'
163									? await verifyReactBoilerplateNode24({ receiptPath })
164									: fixture === 'react-boilerplate-v4-vite8'
165										? await verifyReactBoilerplateVite8({ receiptPath })
166										: fixture === 'react-boilerplate-v4-data-flow'
167											? await verifyReactBoilerplateDataFlow({ receiptPath })
168											: fixture === 'react-boilerplate-v4-composed'
169												? await verifyReactBoilerplateComposed({ receiptPath })
170												: await verifyReactFixture({ receiptPath });
171			console.log(JSON.stringify({ result: 'pass', digest: receipt.integrity.canonicalDigest }));
172		} else if (command === 'framework:classify') {
173			const descriptorPath = valueAfter('--descriptor');
174			if (!descriptorPath) throw new Error('framework:classify requires --descriptor');
175			console.log(
176				JSON.stringify(
177					await runFrameworkClassification({
178						descriptorPath,
179						offline: args.includes('--offline'),
180					}),
181				),
182			);
183		} else if (command === 'nextjs:provenance-classify') {
184			const fixture = valueAfter('--fixture');
185			const outputPath = valueAfter('--output');
186			if (!fixture || !outputPath || !args.includes('--offline'))
187				throw new Error(
188					'nextjs:provenance-classify requires --offline, --fixture, and --output',
189				);
190			const receipt = await runNextjsProvenanceClassification({
191				fixtureId: fixture,
192				outputPath,
193				offline: true,
194			});
195			console.log(
196				JSON.stringify({
197					result: 'pass',
198					fixture: receipt.closure.fixtureId,
199					digest: receipt.integrity.canonicalDigest,
200					networkAttempts: receipt.locality.networkAttempts,
201					candidateExecution: receipt.locality.candidateExecution,
202				}),
203			);
204		} else if (command === 'next13:provenance-classify') {
205			const fixture = valueAfter('--fixture');
206			const outputPath = valueAfter('--output');
207			if (!fixture || !outputPath || !args.includes('--offline'))
208				throw new Error(
209					'next13:provenance-classify requires --offline, --fixture, and --output',
210				);
211			const receipt = await runNext13ProvenanceClassification({
212				fixtureId: fixture,
213				outputPath,
214				offline: true,
215			});
216			console.log(
217				JSON.stringify({
218					result: 'pass',
219					fixture: receipt.closure.fixtureId,
220					digest: receipt.integrity.canonicalDigest,
221					networkAttempts: receipt.locality.networkAttempts,
222					candidateExecution: receipt.locality.candidateExecution,
223				}),
224			);
225		} else if (command === 'dependency:ingest' || command === 'dependency:verify') {
226			const fixture = valueAfter('--fixture');
227			if (fixture !== 'angular-fuxa')
228				throw new Error('Dependency closure requires --fixture angular-fuxa');
229			const dependencyArgs = [...args];
230			if (command === 'dependency:verify' && !dependencyArgs.includes('--verify-only'))
231				dependencyArgs.push('--verify-only');
232			await runAngularFuxaDependencyIngest(dependencyArgs);
233		} else if (command === 'angular-fuxa:standalone') {
234			await runAngularFuxaStandalone(args);
235		} else if (command === 'angular-fuxa:standalone-cohort') {
236			await runAngularFuxaStandaloneCohort(args);
237		} else if (command === 'angular-fuxa:template-compiler') {
238			await runAngularFuxaTemplateCompiler(args);
239		} else if (command === 'vite8:shared-adapter-cohort') {
240			await runVite8SharedAdapterCohort(args);
241		} else if (command === 'receipt:verify') {
242			const flags = args.filter((arg) => arg.startsWith('--'));
243			const paths = args.filter((arg) => !arg.startsWith('--'));
244			if (flags.some((flag) => flag !== '--pre-integration' && flag !== '--offline'))
245				throw new Error('receipt:verify received an unknown flag');
246			if (flags.filter((flag) => flag === '--pre-integration').length > 1)
247				throw new Error('receipt:verify received duplicate --pre-integration flags');
248			if (paths.length > 1)
249				throw new Error(
250					'receipt:verify requires exactly one receipt path when a path is supplied',
251				);
252			const preIntegration = flags.includes('--pre-integration');
253			if (preIntegration && paths.length !== 1)
254				throw new Error('receipt:verify --pre-integration requires exactly one receipt path');
255			const file = paths[0] ?? 'evidence/runs/react-boilerplate-v4-composed/t060-run.json';
256			if (
257				preIntegration &&
258				(process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
259					process.env.NPM_CONFIG_OFFLINE !== 'true')
260			)
261				throw new Error('receipt:verify --pre-integration requires dual offline controls');
262			console.log(
263				JSON.stringify(await verifyReceipt(file, { requireAggregate: !preIntegration })),
264			);
265		} else if (command === 'corpus:verify') {
266			if (process.env.VERSIONLESS_NETWORK_MODE !== 'offline' && !args.includes('--offline'))
267				throw new Error('corpus:verify requires VERSIONLESS_NETWORK_MODE=offline');
268			const result = await analyzeCorpusConformance();
269			console.log(
270				JSON.stringify({
271					result: 'pass',
272					digest: result.integrity.canonicalDigest,
273					verticals: result.summary.verticals,
274					sourceApplications: result.summary.sourceApplications,
275				}),
276			);
277		} else if (command === 'script-surface:verify') {
278			const result = await verifyScriptSurface();
279			console.log(
280				JSON.stringify({
281					result: 'pass',
282					verticals: result.summary.verticals,
283					sourceApplications: result.summary.sourceApplications,
284					lanes: result.summary.lanes,
285					externalScriptsIntroduced: result.summary.externalScriptsIntroduced,
286				}),
287			);
288		} else if (command === 'runtime-script-observation:verify') {
289			const configPath = valueAfter('--config');
290			const outputDir = valueAfter('--output');
291			if (!configPath || !outputDir || !args.includes('--offline'))
292				throw new Error(
293					'runtime-script-observation:verify requires --offline, --config, and --output',
294				);
295			const result = await verifyRuntimeScriptObservation({
296				configPath,
297				outputDir,
298				offline: true,
299			});
300			console.log(JSON.stringify({ result: 'pass', ...result.summary }));
301		} else if (command === 'direct-dom:inventory') {
302			const root = valueAfter('--root');
303			const id = valueAfter('--id');
304			const output = valueAfter('--output');
305			if (!root || !id || !output || !args.includes('--offline'))
306				throw new Error('direct-dom:inventory requires --offline, --root, --id, and --output');
307			const inventory = runDirectDomInventory({ root, id, output, offline: true });
308			console.log(
309				JSON.stringify({
310					result: 'pass',
311					id: inventory.id,
312					files: inventory.semanticEngine.files,
313					sites: inventory.counts.total,
314					digest: inventory.integrity.canonicalDigest,
315					networkAttempts: inventory.locality.networkAttempts,
316				}),
317			);
318		} else if (command === 'witness:real-app') {
319			if (args.includes('--verify-provenance-only')) {
320				console.log(JSON.stringify(await verifyLinkedWitnessProvenance()));
321			} else if (args.includes('--journeys') || valueAfter('--baseline') !== undefined) {
322				/**
323				 * The synthesized-journey path. It is reached by declaring a lane pair,
324				 * because a run against journeys nobody authored has to be pointed at the
325				 * lanes it is about — there is no frozen corpus entry to look them up in.
326				 * `--journeys synthesized` forces synthesis even for an application that
327				 * HAS a hand-authored driver, and the record then says the driver was
328				 * overridden rather than absent.
329				 */
330				const application = valueAfter('--app');
331				const baseline = valueAfter('--baseline');
332				const migrated = valueAfter('--migrated');
333				if (!application || !baseline)
334					throw new Error(
335						'witness:real-app synthesized journeys require --app and --baseline (and usually --migrated)',
336					);
337				const declaration = readJourneyDeclaration(valueAfter('--journeys'));
338				const framework = (valueAfter('--framework') ??
339					'react') as WitnessRealAppRun['framework'];
340				const record = await runSynthesizedWitnessRealApp({
341					application,
342					framework,
343					declaration,
344					lanes: [
345						{ lane: 'baseline' as const, laneRoot: baseline },
346						...(migrated === undefined
347							? []
348							: [{ lane: 'migrated' as const, laneRoot: migrated }]),
349					],
350					...(valueAfter('--source-root') === undefined
351						? {}
352						: { sourceRoot: valueAfter('--source-root') }),
353					output: valueAfter('--out') ?? synthesizedWitnessOutputDir(application),
354				});
355				console.log(
356					JSON.stringify({
357						result: 'pass',
358						journeySource: record.journeySource,
359						overridden: record.selection.overridden,
360						replayabilityRatio: record.synthesized.replayabilityRatio,
361						digest: record.integrity.canonicalDigest,
362					}),
363				);
364			} else {
365				const publish = valueAfter('--publish');
366				const verify = valueAfter('--verify');
367				if (publish && args.includes('--run-twice')) {
368					const receipt = await runWitnessRealApps(publish);
369					console.log(
370						JSON.stringify({
371							result: receipt.result,
372							digest: receipt.integrity.canonicalDigest,
373						}),
374					);
375				} else if (verify) {
376					const receipt = await verifyWitnessRealApps(verify);
377					console.log(
378						JSON.stringify({
379							result: receipt.result,
380							digest: receipt.integrity.canonicalDigest,
381						}),
382					);
383				} else {
384					throw new Error(
385						'witness:real-app requires --verify-provenance-only, --run-twice --publish, or --verify',
386					);
387				}
388			}
389		} else if (command === 'witness:angular-realworld') {
390			const publish = valueAfter('--publish');
391			const verify = valueAfter('--verify');
392			if (publish && args.includes('--run-twice')) {
393				const receipt = await runWitnessAngularRealworld(publish);
394				console.log(
395					JSON.stringify({
396						result: receipt.result,
397						digest: receipt.integrity.canonicalDigest,
398					}),
399				);
400			} else if (verify) {
401				const receipt = await verifyWitnessAngularRealworld(verify);
402				console.log(
403					JSON.stringify({
404						result: receipt.result,
405						digest: receipt.integrity.canonicalDigest,
406					}),
407				);
408			} else {
409				throw new Error('witness:angular-realworld requires --run-twice --publish or --verify');
410			}
411		} else if (command === 'trust:ingest') {
412			const result = await ingestTrustInputs({
413				allowNetwork: args.includes('--allow-network'),
414				consentId: valueAfter('--consent-id'),
415			});
416			console.log(
417				JSON.stringify({
418					result: 'ingested',
419					purpose: result.purpose,
420					consentId: result.consent.consentId,
421					packages: result.packages.length,
422				}),
423			);
424		} else if (command === 'trust:generate') {
425			const policyPath = valueAfter('--policy');
426			const outputDir = valueAfter('--output');
427			if (!policyPath || !outputDir)
428				throw new Error('trust:generate requires --policy and --output');
429			console.log(
430				JSON.stringify(
431					await generateTrustPackage({
432						offline: args.includes('--offline'),
433						policyPath,
434						outputDir,
435					}),
436				),
437			);
438		} else if (command === 'report:enterprise') {
439			// The operator-facing flow an enterprise reviewer is handed: it verifies the
440			// trust package first, then re-derives the one machine artifact and the one
441			// human document from the same canonical receipts. `--verify-only` refuses
442			// to write, so a reviewer can check the published pair without touching it.
443			const outputDir = valueAfter('--output') ?? 'evidence/trust/current';
444			if (!args.includes('--offline')) throw new Error('report:enterprise requires --offline');
445			const verifyOnly = args.includes('--verify-only');
446			const result = await runEnterpriseReport({
447				outputDir,
448				verifyOnly,
449				environment: { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' },
450			});
451			console.log(JSON.stringify(result));
452		} else if (command === 'report:coverage') {
453			// The coverage half of the same flow, in the same shape: the trust package
454			// is verified before anything is read out of it, and the matrix is read
455			// through `readSupportedMatrix` — the one guarded derivation — rather than
456			// counted again here. `--verify-only` refuses to write, which is the mode a
457			// reviewer runs against a pair they did not generate.
458			//
459			// `trust:generate` and `report:enterprise` already emit this pair beside the
460			// enterprise surfaces; this command is the one that says so on its own, and
461			// re-derives it in isolation.
462			const outputDir = valueAfter('--output') ?? 'evidence/trust/current';
463			if (!args.includes('--offline')) throw new Error('report:coverage requires --offline');
464			const verifyOnly = args.includes('--verify-only');
465			const environment = { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' };
466			const reading = await readSupportedMatrix({ trustDir: outputDir, environment });
467			const output = path.resolve(outputDir);
468			const derived = await deriveCoverageSurfaces({
469				root: path.resolve('.'),
470				output,
471				matrix: reading.matrix,
472				capabilityCoverage: buildCapabilityCoverage(),
473			});
474			if (verifyOnly) await verifyPublishedCoverageSurfaces(output, derived);
475			else {
476				await writeFile(
477					path.join(output, COVERAGE_REPORT_JSON),
478					`${JSON.stringify(derived.report, null, 2)}\n`,
479				);
480				await writeFile(path.join(output, COVERAGE_REPORT_MARKDOWN), derived.markdown);
481			}
482			console.log(
483				JSON.stringify({
484					result: 'pass',
485					mode: verifyOnly ? 'verified' : 'generated',
486					trustDigest: reading.trustDigest,
487					machineArtifact: path.join(outputDir, COVERAGE_REPORT_JSON),
488					humanDocument: path.join(outputDir, COVERAGE_REPORT_MARKDOWN),
489					machineArtifactSha256: sha256(
490						await readFile(path.join(output, COVERAGE_REPORT_JSON)),
491					),
492					humanDocumentSha256: sha256(
493						await readFile(path.join(output, COVERAGE_REPORT_MARKDOWN)),
494					),
495					coverageDigest: derived.report.integrity.canonicalDigest,
496					certification: 'not-certified',
497				}),
498			);
499		} else if (command === 'trust:verify') {
500			const outputDir = args.find((arg) => !arg.startsWith('--'));
501			console.log(
502				JSON.stringify(
503					await verifyTrustPackage({
504						outputDir: outputDir ?? 'evidence/trust/current',
505						compareDir: valueAfter('--compare'),
506						environment: args.includes('--offline')
507							? { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' }
508							: process.env,
509					}),
510				),
511			);
512		} else throw new Error(`Unknown command: ${command}`);
513	} catch (error) {
514		console.error(error instanceof Error ? error.stack : String(error));
515		process.exitCode = 1;
516	}
