863	 *
864	 * `--out` and `--record` are the write set, so they are declared by the harness
865	 * rather than forwarded twice; `--json`, `--help` and `--offline` are this
866	 * command's own reading, not the run's. Everything else travels unchanged,
867	 * because a narrowed run is not the run being scored.
868	 */
869	export function forwardedRunFlags(
870		flags: Readonly<Record<string, readonly string[]>>,
871	): readonly string[] {
872		const settled: readonly string[] = ['--out', '--record', '--json', '--help', '--offline'];
873		const booleans: readonly string[] = BOOLEAN_FLAGS['intervention-count'];
874		const forwarded: string[] = [];
875		for (const flag of Object.keys(flags).sort()) {
876			if (settled.includes(flag)) continue;
877			const values = flags[flag] ?? [];
878			if (booleans.includes(flag)) {
879				forwarded.push(flag);
880				continue;
881			}
882			for (const value of values) forwarded.push(flag, value);
883		}
884		return Object.freeze(forwarded);
885	}
