893	/**
894	 * Run one operator command and return what it would print.
895	 *
896	 * A named refusal is a returned outcome carrying exit 2, not a thrown stack
897	 * trace: a fleet report has to be able to tally the reason an application was
898	 * declined, and an exception with a formatted stack is not a tally. A defect
899	 * still throws — an exception is the honest shape for something that broke —
900	 * and the caller scores it 1.
901	 */
902	export async function runOperatorCommand(
903		command: OperatorCommand,
904		args: readonly string[],
905	): Promise<OperatorOutcome> {
906		try {
907			return await runOperatorFlow(command, args);
908		} catch (error) {
909			const refusal = pipelineRefusalOf(error);
910			if (refusal === null) throw error;
911			const json = refusalRecord(command, refusal);
912			/**
913			 * Read without the parser, because the parser is itself one of the
914			 * stages that can refuse. A refused run still writes its record: the
915			 * refusal is the outcome the fleet report needs, not the absence of one.
916			 */
917			const recordIndex = args.indexOf('--record');
918			await writeRecord(recordIndex < 0 ? undefined : args[recordIndex + 1], json);
919			return Object.freeze({
920				text: args.includes('--json') ? `${JSON.stringify(json)}\n` : renderRefusal(refusal),
