929		args: readonly string[],
930	): Promise<OperatorOutcome> {
931		const parsed = parseOperatorArguments(command, args);
932		if (parsed.help)
933			return Object.freeze({ text: operatorHelp(command), json: { help: command }, exitCode: 0 });
934		const root = parsed.positional[0] ?? '.';
935		const angular = {
936			sourceDirectories: parsed.flags['--source-dir'],
937			templateDirectories: parsed.flags['--template-dir'],
938			styleSheetDirectories: parsed.flags['--style-dir'],
939		};
940		const react = { entryModule: parsed.flags['--entry']?.[0] };
941		const licence: LicencePolicy = Object.freeze({
942			declaredIdentifier: parsed.flags['--license']?.[0] ?? null,
943		});
944		const declarations: IngestDeclarations = Object.freeze({
945			id: parsed.flags['--id']?.[0] ?? null,
946			frontendRoot: parsed.flags['--frontend-root']?.[0] ?? null,
947			revision: parsed.flags['--revision']?.[0] ?? null,
948			repository: parsed.flags['--repository']?.[0] ?? null,
949			ref: parsed.flags['--ref']?.[0] ?? null,
950			lockfile: parsed.flags['--lockfile']?.[0] ?? null,
951			licence,
952		});
953		const eraCellDeclarations: EraCellDeclarations = Object.freeze({
954			...DEFAULT_ERA_CELL_DECLARATIONS,
955			node: parsed.flags['--node']?.[0] ?? null,
956			architecture: parsed.flags['--arch']?.[0] ?? null,
957			cell: parsed.flags['--cell']?.[0] ?? null,
958		});
959		if (command === 'acquire') {
960			const record = await acquireApplicationSource({
961				repository: parsed.positional[0] ?? '',
962				ref: parsed.flags['--ref']?.[0] ?? null,
963				id: parsed.flags['--id']?.[0] ?? null,
964				consentId: parsed.flags['--consent']?.[0] ?? null,
965				declaredLicence: licence.declaredIdentifier,
966			});
967			const json = { flow: 'acquire', ...record };
968			await writeRecord(parsed.flags['--record']?.[0], json);
969			return Object.freeze({
970				text: parsed.json ? `${JSON.stringify(json)}\n` : renderAcquire(record),
971				json,
972				exitCode: EXIT_PROCEEDED,
973			});
974		}
975		if (command === 'ingest') {
976			const record = await ingestApplicationSource(root, declarations);
977			const json = { flow: 'ingest', source: displayPath(root), ...record };
978			await writeRecord(parsed.flags['--record']?.[0], json);
979			return Object.freeze({
980				text: parsed.json ? `${JSON.stringify(json)}\n` : renderIngest(record),
981				json,
982				exitCode: EXIT_PROCEEDED,
983			});
984		}
985		if (command === 'license-at-pin') {
986			const frontendRoot = parsed.flags['--frontend-root']?.[0] ?? '.';
987			const manifest = path.join(root, frontendRoot, 'package.json');
988			const record = await readLicenceAtPin(
989				root,
990				(await fileExists(manifest)) ? manifest : null,
991				licence,
992			);
993			const json = { flow: 'license-at-pin', source: displayPath(root), ...record };
994			await writeRecord(parsed.flags['--record']?.[0], json);
995			return Object.freeze({
996				text: parsed.json ? `${JSON.stringify(json)}\n` : renderLicenceAtPin(record),
997				json,
998				exitCode: EXIT_PROCEEDED,
999			});
1000		}
1001		if (command === 'era-cell') {
1002			/**
1003			 * The host is read before the stage runs, so a refused run still reports
1004			 * what this host carries. A refusal that says only "not available" and
1005			 * not what was there is a refusal an operator cannot act on.
1006			 */
1007			const host = await readHostCell();
1008			let record: EraCellRecord;
1009			try {
1010				record = await establishEraCell(root, eraCellDeclarations, host);
1011			} catch (error) {
1012				const refusal = pipelineRefusalOf(error);
1013				if (refusal === null) throw error;
1014				record = eraCellRefused(refusal, host);
1015				const refused = {
1016					flow: 'era-cell',
1017					application: displayPath(root),
1018					...refusalRecord('era-cell', refusal),
1019					eraCell: record,
1020				};
1021				await writeRecord(parsed.flags['--record']?.[0], refused);
1022				return Object.freeze({
1023					text: parsed.json ? `${JSON.stringify(refused)}\n` : renderRefusal(refusal),
1024					json: refused,
