1026				});
1027			}
1028			const json = { flow: 'era-cell', application: displayPath(root), ...record };
1029			await writeRecord(parsed.flags['--record']?.[0], json);
1030			return Object.freeze({
1031				text: parsed.json ? `${JSON.stringify(json)}\n` : renderEraCell(record),
1032				json,
1033				exitCode: EXIT_PROCEEDED,
1034			});
1035		}
1036		if (command === 'analyze') {
1037			const analysis = await analyzeApplication(root);
1038			const json = { flow: 'analyze', application: displayPath(root), ...analysis };
1039			await writeRecord(parsed.flags['--record']?.[0], json);
1040			return Object.freeze({
1041				text: parsed.json ? `${JSON.stringify(json)}\n` : renderAnalysis(root, analysis),
1042				json,
1043				exitCode: 0,
1044			});
1045		}
1046		if (command === 'plan') {
1047			const { analysis, plan } = await planApplication({ appRoot: root, angular, react });
1048			const json = {
1049				flow: 'plan',
1050				application: displayPath(root),
1051				detected: analysis,
1052				plan: { ...plan, files: plan.files.map(({ source: _source, ...rest }) => rest) },
1053			};
1054			await writeRecord(parsed.flags['--record']?.[0], json);
1055			return Object.freeze({
1056				text: parsed.json ? `${JSON.stringify(json)}\n` : renderPlan(root, plan),
1057				json,
1058				exitCode: 0,
1059			});
1060		}
1061		if (command === 'migrate') {
1062			const out = parsed.flags['--out']?.[0] as string;
1063			/**
