1075							parsed.flags['--source-root']?.[0] ?? root,
1076							declarations,
1077						);
1078			/**
1079			 * The cell is established before the lane is composed and long before
1080			 * anything is installed, because the install runs inside the cell. A cell
1081			 * this host cannot provide is a refusal that arrives before a lane exists,
1082			 * not after a native build failed inside one.
1083			 */
1084			const eraCell =
1085				parsed.flags['--era-cell'] === undefined
1086					? eraCellNotRequested(
