1102				allowPeerConflicts: parsed.flags['--allow-peer-conflicts'] !== undefined,
1103			});
1104			const install =
1105				parsed.flags['--install'] === undefined
1106					? installNotRequested(
1107							'--install was not declared. The lane was composed and not installed, and this run establishes nothing about whether its closure resolves.',
1108						)
