1195			 * own refusal rather than becoming an allowance this flow granted.
1196			 */
1197			const runDeclarations: RunDeclarations = Object.freeze({
1198				appRoot: root,
1199				out: parsed.flags['--out']?.[0] as string,
1200				sourceRoot: parsed.flags['--source-root']?.[0] ?? root,
1201				materialize: parsed.flags['--materialize'] !== undefined,
1202				dryRun: parsed.flags['--dry-run'] !== undefined,
1203				ingest: declarations,
1204				licence,
1205				eraCell: eraCellDeclarations,
1206				angular,
1207				react,
1208				install: Object.freeze({
1209					allowRemoteTarballs: parsed.flags['--allow-remote-tarballs'] !== undefined,
1210					allowInstallScripts: parsed.flags['--allow-install-scripts'] !== undefined,
1211					skipInstallScripts: parsed.flags['--skip-install-scripts'] !== undefined,
1212					allowPeerConflicts: parsed.flags['--allow-peer-conflicts'] !== undefined,
1213				}),
