1216			const record = await runFullPipeline(runDeclarations);
1217			await writeRecord(parsed.flags['--record']?.[0], record);
1218			return Object.freeze({
1219				text: parsed.json ? `${JSON.stringify(record)}\n` : renderRun(record),
1220				json: record,
1221				exitCode: record.exitCode,
1222			});
1223		}
1224		if (command === 'intervention-count') {
1225			/**
1226			 * The harness forwards every declaration `run` owns and adds none of its
1227			 * own beyond where the two records land. What it counts has to be the run
1228			 * an operator would have launched.
1229			 */
1230			const out = parsed.flags['--out']?.[0] as string;
1231			const runRecord = parsed.flags['--record']?.[0] ?? `${out}.run-record.json`;
1232			const forwarded = forwardedRunFlags(parsed.flags);
1233			const record = await countInterventions({
1234				appRoot: root,
1235				out,
1236				runRecord,
1237				root: process.cwd(),
1238				evidencePaths: Object.freeze([]),
1239				attempts: Object.freeze([
1240					runArgvFor(cliEntryPath(), { appRoot: root, out, runRecord }, forwarded),
1241				]),
1242				stageBudgetMs: DEFAULT_STAGE_BUDGET_MS,
1243			});
1244			await writeInterventionRecord(runRecord, record);
1245			return Object.freeze({
1246				text: parsed.json ? `${JSON.stringify(record)}\n` : renderInterventionCount(record),
1247				json: record,
