1249			});
1250		}
1251		if (command === 'refusal-census') {
1252			const census = await buildRefusalCensus();
1253			const target = parsed.flags['--out']?.[0] ?? REFUSAL_CENSUS_FILE;
1254			const verifyOnly = parsed.flags['--verify-only'] !== undefined;
1255			const derived = `${JSON.stringify(census, null, '\t')}\n`;
1256			const published = (await fileExists(path.resolve(target)))
1257				? await readFile(path.resolve(target), 'utf8')
1258				: null;
1259			const matches = published === derived;
1260			if (!verifyOnly) await writeRefusalCensus(census, target);
1261			const json = {
1262				flow: 'refusal-census',
1263				file: target,
1264				verifyOnly,
1265				matchesPublished: matches,
1266				published: published !== null,
1267				census,
1268			};
1269			await writeRecord(parsed.flags['--record']?.[0], json);
1270			return Object.freeze({
1271				text: parsed.json
1272					? `${JSON.stringify(json)}\n`
1273					: renderCensus(census, verifyOnly ? null : target),
1274				json,
1275				exitCode: verifyOnly && !matches ? 1 : EXIT_PROCEEDED,
1276			});
1277		}
1278		if (command === 'witness-synthesize') {
1279			const synthesis = await synthesizeWitnessJourneys({
1280				root,
1281				laneUrl: parsed.flags['--lane-url']?.[0],
1282				crawlBounds: {
1283					maxDepth: readCrawlBound(
1284						'--max-depth',
1285						parsed.flags['--max-depth']?.[0],
1286						CRAWL_DEFAULT_BOUNDS.maxDepth,
1287					),
1288					maxRoutes: readCrawlBound(
1289						'--max-routes',
1290						parsed.flags['--max-routes']?.[0],
1291						CRAWL_DEFAULT_BOUNDS.maxRoutes,
1292					),
1293					requestTimeoutMs: CRAWL_DEFAULT_BOUNDS.requestTimeoutMs,
1294				},
1295			});
1296			const target = parsed.flags['--out']?.[0];
1297			await writeRecord(target, synthesis);
1298			await writeRecord(parsed.flags['--record']?.[0], synthesis);
1299			return Object.freeze({
1300				text: parsed.json
1301					? `${JSON.stringify(synthesis)}\n`
1302					: renderWitnessSynthesis(synthesis, target ?? null),
1303				json: synthesis,
1304				exitCode: EXIT_PROCEEDED,
1305			});
1306		}
1307		if (command === 'verify') {
